const listRedemptions = `-- name: ListRedemptions :many
SELECT iv.id, iv.voucher_id, v.name AS voucher_name, v.voucher_type, v.code_normalized, i.slug AS instance_slug,
       iv.redeemed_at, iv.effective_starts_at, iv.effective_expires_at, iv.applications_count, iv.status,
       iv.expired_at, iv.revoked_at, iv.revoked_reason, v.duration, v.duration_in_periods,
       (v.price_discount_type IS NOT NULL)::boolean AS has_price_part
FROM instance_voucher iv
JOIN voucher v ON v.id = iv.voucher_id AND v.organization_id = iv.organization_id
JOIN instance i ON i.id = iv.instance_id AND i.organization_id = iv.organization_id
WHERE iv.organization_id = $1
  AND ($2::uuid IS NULL OR iv.instance_id = $2)
  AND ($3::uuid IS NULL OR iv.voucher_id = $3)
  AND ($4::uuid IS NULL OR iv.id = $4)
  AND ($5::instance_voucher_status IS NULL OR iv.status = $5)
  AND ($6::timestamp IS NULL
    OR (iv.redeemed_at, iv.id) < ($6::timestamp, $7::uuid))
ORDER BY iv.redeemed_at DESC, iv.id DESC
LIMIT $8::integer
`

type ListRedemptionsParams struct {
	OrganizationID uuid.UUID              `json:"organization_id"`
	InstanceID     *uuid.UUID             `json:"instance_id"`
	VoucherID      *uuid.UUID             `json:"voucher_id"`
	ID             *uuid.UUID             `json:"id"`
	Status         *InstanceVoucherStatus `json:"status"`
	CursorAt       pgtype.Timestamp       `json:"cursor_at"`
	CursorID       *uuid.UUID             `json:"cursor_id"`
	RowLimit       *int32                 `json:"row_limit"`
}

type ListRedemptionsRow struct {
	ID                 uuid.UUID             `json:"id"`
	VoucherID          uuid.UUID             `json:"voucher_id"`
	VoucherName        string                `json:"voucher_name"`
	VoucherType        VoucherType           `json:"voucher_type"`
	CodeNormalized     *string               `json:"code_normalized"`
	InstanceSlug       string                `json:"instance_slug"`
	RedeemedAt         pgtype.Timestamp      `json:"redeemed_at"`
	EffectiveStartsAt  pgtype.Timestamp      `json:"effective_starts_at"`
	EffectiveExpiresAt pgtype.Timestamp      `json:"effective_expires_at"`
	ApplicationsCount  int32                 `json:"applications_count"`
	Status             InstanceVoucherStatus `json:"status"`
	ExpiredAt          pgtype.Timestamp      `json:"expired_at"`
	RevokedAt          pgtype.Timestamp      `json:"revoked_at"`
	RevokedReason      *string               `json:"revoked_reason"`
	Duration           VoucherDuration       `json:"duration"`
	DurationInPeriods  *int32                `json:"duration_in_periods"`
	HasPricePart       bool                  `json:"has_price_part"`
}

// NULL reads every match: an instance's redemptions, and the single reads.
func (q *Queries) ListRedemptions(ctx context.Context, arg ListRedemptionsParams) ([]ListRedemptionsRow, error) {
	rows, err := q.db.Query(ctx, listRedemptions,
		arg.OrganizationID,
		arg.InstanceID,
		arg.VoucherID,
		arg.ID,
		arg.Status,
		arg.CursorAt,
		arg.CursorID,
		arg.RowLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListRedemptionsRow
	for rows.Next() {
		var i ListRedemptionsRow
		if err := rows.Scan(
			&i.ID,
			&i.VoucherID,
			&i.VoucherName,
			&i.VoucherType,
			&i.CodeNormalized,
			&i.InstanceSlug,
			&i.RedeemedAt,
			&i.EffectiveStartsAt,
			&i.EffectiveExpiresAt,
			&i.ApplicationsCount,
			&i.Status,
			&i.ExpiredAt,
			&i.RevokedAt,
			&i.RevokedReason,
			&i.Duration,
			&i.DurationInPeriods,
			&i.HasPricePart,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

